// 递归创建嵌套目录结构
async function mkdirp(rootHandle, path) {
  const parts = path.split('/').filter(Boolean);
  let current = rootHandle;
  for (const part of parts) {
    current = await current.getDirectoryHandle(part, { create: true });
  }
  return current;
}

